test('scorecard draft helpers normalize context and hole payloads for per-hole persistence', () => {
  const context = normalizeDraftContext({ mode: 'solo', date: '2026-05-16', state: 'ut', course: ' Alpine Country Club ' }, { id: 'user-1', email: 'PLAYER@EXAMPLE.COM' })
  assert.equal(context.mode, 'solo')
  assert.equal(context.state, 'UT')
  assert.equal(context.course, 'Alpine Country Club')
  assert.equal(context.teamKey, '')
  assert.equal(context.scoringSide, 'team')

  const teamContext = normalizeDraftContext({ mode: 'team', date: '2026-05-16', state: 'UT', course: 'Alpine', team: 'Wolf Pack', opponentTeam: 'Visitors' }, { id: 'user-1', email: 'player@example.com' })
  assert.equal(teamContext.teamKey, 'wolf pack')
  assert.equal(teamContext.opponentTeamKey, 'visitors')
  assert.equal(teamContext.scoringSide, 'team')
  const opponentContext = normalizeDraftContext({ mode: 'team', date: '2026-05-16', state: 'UT', course: 'Alpine', team: 'Wolf Pack', opponentTeam: 'Visitors', scoringSide: 'opponent' }, { id: 'user-1', email: 'player@example.com' })
  assert.equal(opponentContext.scoringSide, 'opponent')
  assert.equal(buildScorecardDraftId(teamContext, 7), buildScorecardDraftId(teamContext, 7))
  assert.notEqual(buildScorecardDraftId(teamContext, 7), buildScorecardDraftId(teamContext, 8))
  assert.notEqual(buildScorecardDraftId(teamContext, 7), buildScorecardDraftId(opponentContext, 7))

  assert.deepEqual(normalizeDraftHole({ hole: { hole: 7, par: 4, yards: 385, strokeIndex: 9, score: 5 } }), {
    hole: 7,
    par: 4,
    yards: 385,
    strokeIndex: 9,
    score: 5,
    scoreProvided: true,
  })
  assert.deepEqual(normalizeDraftHole({ hole: { hole: 8, par: 4, yards: null, strokeIndex: null, score: 4 } }), {
    hole: 8,
    par: 4,
    yards: null,
    strokeIndex: null,
    score: 4,
    scoreProvided: true,
  })
  assert.throws(() => normalizeDraftHole({ hole: 19, score: 4 }), /hole must be between 1 and 18/)
})

