test('organizer tournament edit form moves registration deadline below date and hides descriptions outside edit mode', () => {
  const organizerPage = fs.readFileSync(new URL('../src/pages/OrganizerTournaments.tsx', import.meta.url), 'utf8')
  const hostPage = fs.readFileSync(new URL('../src/pages/HostPortal.tsx', import.meta.url), 'utf8')
  const templateFields = fs.readFileSync(new URL('../src/components/TournamentTemplateFields.tsx', import.meta.url), 'utf8')

  const organizerStatusIndex = organizerPage.indexOf('<label className="label">Status</label>')
  const organizerNameIndex = organizerPage.indexOf('<label className="label">Tournament name</label>')
  const hostEditFormIndex = hostPage.indexOf('<RegisteredGolfers tournament={tournament} />')
  const hostStatusIndex = hostPage.indexOf('<label className="label">Status</label>', hostEditFormIndex)
  const hostNameIndex = hostPage.indexOf('<label className="label">Tournament name</label>', hostEditFormIndex)
  const dateIndex = organizerPage.indexOf('Tournament date')
  const deadlineIndex = organizerPage.indexOf('<TournamentRegistrationDeadlineField value={form}')
  const teamLimitIndex = organizerPage.indexOf('Number of teams to play in the tournament')
  assert.equal(organizerStatusIndex > -1 && organizerNameIndex > organizerStatusIndex, true)
  assert.equal(hostStatusIndex > -1 && hostNameIndex > hostStatusIndex, true)
  assert.equal(dateIndex > -1 && deadlineIndex > dateIndex && deadlineIndex < teamLimitIndex, true)
  assert.match(organizerPage, /hideRegistrationDeadline/)
  assert.match(hostPage, /hideRegistrationDeadline/)
  assert.match(templateFields, /hideRegistrationDeadline\?: boolean/)
  assert.match(templateFields, /export function TournamentRegistrationDeadlineField/)
  assert.match(templateFields, /!hideRegistrationDeadline \? <TournamentRegistrationDeadlineField/)
  assert.doesNotMatch(organizerPage, /\{tournament\.description \? <div className="small">/)
})

